from pwn import *
import string

def generate_inputs():
    # Generate inputs with the flag format in mind: csawctf{...}
    charset = string.ascii_letters + string.digits + "{}_"
    prefix = "csawctf{"
    suffix = "}"

    for c1 in charset:
        for c2 in charset:
            for c3 in charset:
                # Here, we brute force only 3 characters. Change as per need.
                yield prefix + c1 + c2 + c3 + suffix


def test_input(input):
    # Start the process
    p = process('/home/ctfplayer/ctf_files/prog')

    # Send the input and receive the result
    p.sendline(input)
    response = p.recvall(timeout=1).decode()

    # Close process after testing
    p.close()

    # Check if response indicates correct input
    if "Correct!" in response:
        return True, input
    return False, None


def main():
    for test in generate_inputs():
        success, flag = test_input(test)
        if success:
            print(f"Flag found: {flag}")
            break


if __name__ == "__main__":
    main()

